def interact():
    def query(c, d):
        print(f"? {c} {d}", flush=True)
        return int(input().strip())

    a_xor_c = [0] * 30
    b_xor_c = [0] * 30

    for i in range(30):
        result = query(1 << i, 0)
        if result == 1:
            a_xor_c[i] = 1
        elif result == -1:
            b_xor_c[i] = 1

    a = 0
    b = 0
    for i in range(30):
        if a_xor_c[i]:
            a |= (1 << i)
        if b_xor_c[i]:
            b |= (1 << i)

    print(f"! {a} {b}", flush=True)

interact()
